local fn = {}

function fn.memoize(f)
    local cache, known = {}, {}
    return function(x)
        if not known[x] then
            cache[x] = f(x)
            known[x] = true
        end
        return cache[x]
    end
end

function fn.once(f)
    local done, results = false, nil
    return function(...)
        if not done then
            results = table.pack(f(...))
            done = true
        end
        return table.unpack(results, 1, results.n)
    end
end

function fn.partial(f, ...)
    local first = table.pack(...)
    return function(...)
        local rest = table.pack(...)
        local all = {}
        for i = 1, first.n do all[i] = first[i] end
        for i = 1, rest.n do all[first.n + i] = rest[i] end
        return f(table.unpack(all, 1, first.n + rest.n))
    end
end

function fn.pipe(...)
    local fs = table.pack(...)
    return function(x)
        for i = 1, fs.n do x = fs[i](x) end
        return x
    end
end

function fn.count_calls(f)
    local calls = 0
    local wrapped = function(...)
        calls = calls + 1
        return f(...)
    end
    return wrapped, function() return calls end
end

return fn
